function l(e,r,o){const t=Date.now();return JSON.parse(localStorage.getItem(`rl_${e}`)||"[]").filter(n=>t-n<o).length<r}function g(e){const r=Date.now(),t=JSON.parse(localStorage.getItem(`rl_${e}`)||"[]").filter(s=>r-s<60*60*1e3);t.push(r),localStorage.setItem(`rl_${e}`,JSON.stringify(t))}function i(e,r,o){const t=Date.now(),c=JSON.parse(localStorage.getItem(`rl_${e}`)||"[]").filter(n=>t-n<o).sort((n,a)=>n-a);return c.length<r?0:o-(t-c[0])}export{l as c,i as g,g as r};
